	private FrontierJoinEstimate estimatePathProgram(FrontierJoinProgram program, Scratch scratch) throws IOException {
		double[] leafRows = new double[program.patternCount()];
		double productBound = 1.0d;
		for (int pattern = 0; pattern < program.patternCount(); pattern++) {
			FrontierLeafEstimate estimate = estimateLeaf(program.pattern(pattern), scratch);
			if (estimate.fallbackReason() != FrontierFallbackReason.NONE) {
				return FrontierJoinEstimate.unavailable(estimate.fallbackReason());
			}
			if (estimate.upperRows() == 0.0d) {
				return new FrontierJoinEstimate(0.0d, 0.0d, 0.0d, 1.0d,
						"frontier-v2-omni-path", FrontierFallbackReason.NONE);
			}
			leafRows[pattern] = estimate.pointRows();
			productBound = saturatedMultiply(productBound, estimate.upperRows());
		}
		PathOrder topology = connectedPathOrder(program, leafRows, smallestLeaf(leafRows));
		if (topology == null) {
			return FrontierJoinEstimate.unavailable(FrontierFallbackReason.UNSUPPORTED_QUERY_SHAPE);
		}
		double[] lanePoints = scratch.joinLanePoints(layout.designLanes());
		long sharedWitnesses = Long.MAX_VALUE;
		int available = 0;
		for (int lane = 0; lane < layout.designLanes(); lane++) {
			PathOrder order = supportedPathOrder(program, leafRows, lane, scratch);
			if (order == null) {
				continue;
			}
			PathLaneEstimate estimate = estimatePathLane(program, order.patterns(), lane, scratch);
			if (!estimate.available()) {
				continue;
			}
			if (estimate.exact()) {
				double exact = Math.min(productBound, estimate.point());
				return new FrontierJoinEstimate(exact, exact, exact, 1.0d,
						topology.cyclic() ? "frontier-v2-omni-cycle" : "frontier-v2-omni-path",
						FrontierFallbackReason.NONE);
			}
			lanePoints[available++] = Math.min(productBound, estimate.point());
			sharedWitnesses = Math.min(sharedWitnesses, estimate.witnesses());
		}
		if (available == 0) {
			return FrontierJoinEstimate.unavailable(FrontierFallbackReason.CONFIDENCE_TOO_WIDE);
		}
		return sampledJoinEstimate(lanePoints, available, sharedWitnesses, productBound,
				program.patternCount(), topology.cyclic() ? "frontier-v2-omni-cycle" : "frontier-v2-omni-path");
	}

	private PathOrder supportedPathOrder(FrontierJoinProgram program, double[] leafRows, int lane, Scratch scratch)
			throws IOException {
		int anchor = -1;
		for (int pattern = 0; pattern < program.patternCount(); pattern++) {
			SingleLaneEstimate support = estimateSingleLaneDetailed(program.pattern(pattern), lane, scratch);
			if (support.available() && support.point() > 0.0d
					&& (anchor < 0 || leafRows[pattern] < leafRows[anchor])) {
				anchor = pattern;
			}
		}
		return anchor < 0 ? null : connectedPathOrder(program, leafRows, anchor);
	}

	private PathLaneEstimate estimatePathLane(FrontierJoinProgram program, int[] order, int lane, Scratch scratch)
			throws IOException {
		int maximumClass = program.maximumVariableClass();
		int rowWidth = maximumClass + 1;
		ParticleBuffer current = scratch.firstParticles(rowWidth);
		ParticleBuffer next = scratch.secondParticles(rowWidth);
		TupleBuffer tuples = scratch.tuples();
		boolean[] knownClasses = scratch.knownClasses(rowWidth);
		boolean exact = true;
		long witnesses = Long.MAX_VALUE;
		long work = 0L;

		int anchor = order[0];
		FrontierLeafProbe anchorProbe = program.pattern(anchor);
		for (int plane = 0; plane < FrontierOmniLayout.PLANE_COUNT; plane++) {
			if ((anchorProbe.planeMask() & 1 << plane) == 0) {
				continue;
			}
			tuples.clear();
			LaneEstimate estimate = scanLane(plane, lane, anchorProbe, tuples::add, scratch);
			if (!estimate.available || tuples.overflowed()) {
				return PathLaneEstimate.UNAVAILABLE;
			}
			if (tuples.size() == 0 && !estimate.exact) {
				return PathLaneEstimate.UNAVAILABLE;
			}
			double inclusion = estimate.rowInclusionProbability();
			if (!(inclusion > 0.0d)) {
				return PathLaneEstimate.UNAVAILABLE;
			}
			exact &= estimate.exact;
			witnesses = Math.min(witnesses, estimate.witnesses);
			work += tuples.size();
			if (work > MAXIMUM_PATH_WORK) {
				return PathLaneEstimate.UNAVAILABLE;
			}
			for (int tuple = 0; tuple < tuples.size(); tuple++) {
				if (!current.add(null, -1, program, anchor, knownClasses, tuples, tuple, 1.0d / inclusion)) {
					return PathLaneEstimate.UNAVAILABLE;
				}
			}
		}
		exact &= !current.finishSampling();
		markKnownClasses(program, anchor, knownClasses);

		for (int step = 1; step < order.length; step++) {
			int pattern = order[step];
			next.clear();
			int patternLane = (lane + step) % layout.designLanes();
			FrontierLeafProbe baseProbe = program.pattern(pattern);
			for (int particle = 0; particle < current.size(); particle++) {
				FrontierLeafProbe bound = bindKnownVariables(
						program, pattern, baseProbe, knownClasses, current, particle);
				if (bound == null) {
					continue;
				}
				for (int plane = 0; plane < FrontierOmniLayout.PLANE_COUNT; plane++) {
					if ((bound.planeMask() & 1 << plane) == 0) {
						continue;
					}
					tuples.clear();
					LaneEstimate estimate = scanLane(plane, patternLane, bound, tuples::add, scratch);
					if (!estimate.available || tuples.overflowed()) {
						return PathLaneEstimate.UNAVAILABLE;
					}
					double inclusion = estimate.rowInclusionProbability();
					if (!(inclusion > 0.0d)) {
						return PathLaneEstimate.UNAVAILABLE;
					}
					exact &= estimate.exact;
					witnesses = Math.min(witnesses, estimate.witnesses);
					work = saturatedWorkAdd(work, tuples.size() + 1L);
					if (work > MAXIMUM_PATH_WORK) {
						return PathLaneEstimate.UNAVAILABLE;
					}
					double outputWeight = current.weight(particle) / inclusion;
					for (int tuple = 0; tuple < tuples.size(); tuple++) {
						if (!next.add(current, particle, program, pattern, knownClasses, tuples, tuple,
								outputWeight)) {
							return PathLaneEstimate.UNAVAILABLE;
						}
					}
				}
			}
			exact &= !next.finishSampling();
			markKnownClasses(program, pattern, knownClasses);
			ParticleBuffer swap = current;
			current = next;
			next = swap;
		}
		return new PathLaneEstimate(true, current.totalWeight(), exact,
				witnesses == Long.MAX_VALUE ? 0L : witnesses);
	}

	private static long saturatedWorkAdd(long left, long right) {
		return left >= MAXIMUM_PATH_WORK || right >= MAXIMUM_PATH_WORK - left
				? MAXIMUM_PATH_WORK + 1L
				: left + right;
	}

	private static FrontierLeafProbe bindKnownVariables(FrontierJoinProgram program, int pattern,
			FrontierLeafProbe probe, boolean[] knownClasses, ParticleBuffer particles, int particle) {
		int componentMask = 0;
		long subject = probe.subjectId();
		long predicate = probe.predicateId();
		long object = probe.objectId();
		long context = probe.contextId();
		for (int component = 0; component < FrontierOmniLayout.COMPONENT_COUNT; component++) {
			int variableClass = program.variableClass(pattern, component);
			if (variableClass == 0 || !knownClasses[variableClass]) {
				continue;
			}
			long value = particles.value(particle, variableClass);
			if (!validComponentValue(component, value)) {
				return null;
			}
			componentMask |= 1 << component;
			switch (component) {
			case 0 -> subject = value;
			case 1 -> predicate = value;
			case 2 -> object = value;
			case 3 -> context = value;
			default -> throw new AssertionError();
			}
		}
		return componentMask == 0 ? null : bind(probe, componentMask, subject, predicate, object, context);
	}

	private static void markKnownClasses(FrontierJoinProgram program, int pattern, boolean[] knownClasses) {
		for (int component = 0; component < FrontierOmniLayout.COMPONENT_COUNT; component++) {
			int variableClass = program.variableClass(pattern, component);
			if (variableClass != 0) {
				knownClasses[variableClass] = true;
			}
		}
	}

	private static int smallestLeaf(double[] leafRows) {
		int smallest = 0;
		for (int pattern = 1; pattern < leafRows.length; pattern++) {
			if (leafRows[pattern] < leafRows[smallest]) {
				smallest = pattern;
			}
		}
		return smallest;
	}

	private static PathOrder connectedPathOrder(FrontierJoinProgram program, double[] leafRows, int anchor) {
		int[] order = new int[program.patternCount()];
		boolean[] selected = new boolean[program.patternCount()];
		boolean[] knownClasses = new boolean[program.maximumVariableClass() + 1];
		order[0] = anchor;
		selected[anchor] = true;
		markKnownClasses(program, anchor, knownClasses);
		boolean cyclic = false;
		for (int step = 1; step < order.length; step++) {
			int next = -1;
			for (int pattern = 0; pattern < program.patternCount(); pattern++) {
				if (selected[pattern] || sharedKnownClassCount(program, pattern, knownClasses) == 0) {
					continue;
				}
				if (next < 0 || leafRows[pattern] < leafRows[next]) {
					next = pattern;
				}
			}
			if (next < 0) {
				return null;
			}
			cyclic |= sharedKnownClassCount(program, next, knownClasses) > 1;
			order[step] = next;
			selected[next] = true;
			markKnownClasses(program, next, knownClasses);
		}
		return new PathOrder(order, cyclic);
	}

	private static int sharedKnownClassCount(FrontierJoinProgram program, int pattern, boolean[] knownClasses) {
		int count = 0;
		for (int component = 0; component < FrontierOmniLayout.COMPONENT_COUNT; component++) {
			int variableClass = program.variableClass(pattern, component);
			if (variableClass == 0 || !knownClasses[variableClass]) {
				continue;
			}
			boolean first = true;
			for (int prior = 0; prior < component; prior++) {
				first &= program.variableClass(pattern, prior) != variableClass;
			}
			count += first ? 1 : 0;
		}
		return count;
	}

	private StarLaneEstimate estimateStarLane(FrontierJoinProgram program, int centerVariableClass,
			int[] centerComponents, int anchor, int lane, Scratch scratch) throws IOException {
		FrontierLeafProbe anchorProbe = program.pattern(anchor);
		double point = 0.0d;
		long witnesses = Long.MAX_VALUE;
		boolean exact = true;
		for (int plane = 0; plane < FrontierOmniLayout.PLANE_COUNT; plane++) {
			if ((anchorProbe.planeMask() & 1 << plane) == 0) {
				continue;
			}
			LongCountMap centers = scratch.counts();
			int anchorComponent = centerComponents[anchor];
			LaneEstimate sampledRows = scanLane(plane, lane, anchorProbe,
					(priority, subject, predicate, object, context) -> centers.add(
							componentValue(anchorComponent, subject, predicate, object, context)),
					scratch);
			if (!sampledRows.available || centers.overflowed()) {
				return StarLaneEstimate.UNAVAILABLE;
			}
			if (centers.size() == 0 && !sampledRows.exact) {
				return StarLaneEstimate.UNAVAILABLE;
			}
			double inclusion = sampledRows.rowInclusionProbability();
			if (!(inclusion > 0.0d)) {
				return StarLaneEstimate.UNAVAILABLE;
			}
			exact &= sampledRows.exact;
			witnesses = Math.min(witnesses, sampledRows.witnesses);
			for (int slot = 0; slot < centers.keys().length; slot++) {
				long center = centers.keys()[slot];
				if (center != 0L) {
					StarContribution contribution = starContribution(program, centerVariableClass, anchor, lane,
							center, centers.counts()[slot] / inclusion, scratch);
					if (!contribution.available()) {
						return StarLaneEstimate.UNAVAILABLE;
					}
					point = saturatedAdd(point, contribution.point());
					exact &= contribution.exact();
					witnesses = Math.min(witnesses, contribution.witnesses());
				}
			}
			if (centers.zeroCount() != 0L) {
				StarContribution contribution = starContribution(program, centerVariableClass, anchor, lane,
						0L, centers.zeroCount() / inclusion, scratch);
				if (!contribution.available()) {
					return StarLaneEstimate.UNAVAILABLE;
				}
				point = saturatedAdd(point, contribution.point());
				exact &= contribution.exact();
				witnesses = Math.min(witnesses, contribution.witnesses());
			}
		}
		return new StarLaneEstimate(true, point, exact, witnesses == Long.MAX_VALUE ? 0L : witnesses);
	}

	private StarContribution starContribution(FrontierJoinProgram program, int centerVariableClass, int anchor,
			int lane, long center, double anchorWeight, Scratch scratch) throws IOException {
		double contribution = anchorWeight;
		long witnesses = Long.MAX_VALUE;
		boolean exact = true;
		for (int pattern = 0; pattern < program.patternCount(); pattern++) {
			if (pattern == anchor) {
				continue;
			}
			FrontierLeafProbe bound = bindVariableClass(program, pattern, centerVariableClass, center);
			if (bound == null) {
				return new StarContribution(true, 0.0d, true, 0L);
			}
			int crossLane = (lane + 1 + pattern) % layout.designLanes();
			SingleLaneEstimate degree = estimateSingleLaneDetailed(bound, crossLane, scratch);
			if (!usableConditionalDegree(degree)) {
				return StarContribution.UNAVAILABLE;
			}
			contribution = saturatedMultiply(contribution, degree.point());
			exact &= degree.exact();
			witnesses = Math.min(witnesses, degree.witnesses());
		}
		return new StarContribution(true, contribution, exact, witnesses == Long.MAX_VALUE ? 0L : witnesses);
	}

	private static FrontierLeafProbe bindVariableClass(FrontierJoinProgram program, int pattern,
			int variableClass, long value) {
		int componentMask = 0;
		for (int component = 0; component < FrontierOmniLayout.COMPONENT_COUNT; component++) {
			if (program.variableClass(pattern, component) == variableClass) {
				if (!validComponentValue(component, value)) {
					return null;
				}
				componentMask |= 1 << component;
			}
		}
		return bind(program.pattern(pattern), componentMask, value, value, value, value);
	}

	private static int starCenterVariableClass(FrontierJoinProgram program) {
		int center = 0;
		for (int component = 0; component < FrontierOmniLayout.COMPONENT_COUNT; component++) {
			int candidate = program.variableClass(0, component);
			if (candidate == 0 || candidate == center || !appearsInEveryPattern(program, candidate)) {
				continue;
			}
			if (center != 0) {
				return 0;
			}
			center = candidate;
		}
		if (center == 0) {
			return 0;
		}
		for (int pattern = 0; pattern < program.patternCount(); pattern++) {
			for (int component = 0; component < FrontierOmniLayout.COMPONENT_COUNT; component++) {
				int candidate = program.variableClass(pattern, component);
				if (candidate != 0 && candidate != center && appearsInAnotherPattern(program, pattern, candidate)) {
					return 0;
				}
			}
		}
		return center;
	}

	private static boolean appearsInEveryPattern(FrontierJoinProgram program, int variableClass) {
		for (int pattern = 0; pattern < program.patternCount(); pattern++) {
			if (firstComponent(program, pattern, variableClass) < 0) {
				return false;
			}
		}
		return true;
	}

	private static boolean appearsInAnotherPattern(FrontierJoinProgram program, int ownPattern,
			int variableClass) {
		for (int pattern = 0; pattern < program.patternCount(); pattern++) {
			if (pattern != ownPattern && firstComponent(program, pattern, variableClass) >= 0) {
				return true;
			}
		}
		return false;
	}

	private static int firstComponent(FrontierJoinProgram program, int pattern, int variableClass) {
		for (int component = 0; component < FrontierOmniLayout.COMPONENT_COUNT; component++) {
			if (program.variableClass(pattern, component) == variableClass) {
				return component;
			}
		}
		return -1;
	}

	private FrontierJoinEstimate estimateCompositeBridge(FrontierLeafProbe sampled, FrontierLeafProbe probed,
			int crossComponentPairMask, Scratch scratch) throws IOException {
		if (sampled.boundMask() == 0 || probed.boundMask() == 0) {
			return FrontierJoinEstimate.unavailable(FrontierFallbackReason.UNSUPPORTED_QUERY_SHAPE);
		}
		double[] lanePoints = scratch.joinLanePoints(layout.designLanes());
		long sharedWitnesses = Long.MAX_VALUE;
		int available = 0;
		for (int lane = 0; lane < layout.designLanes(); lane++) {
			int crossLane = layout.designLanes() == 1 ? lane : (lane + 1) % layout.designLanes();
			double lanePoint = 0.0d;
			long laneWitnesses = Long.MAX_VALUE;
			boolean laneAvailable = true;
			boolean laneExact = true;
			for (int plane = 0; plane < FrontierOmniLayout.PLANE_COUNT; plane++) {
				if ((sampled.planeMask() & 1 << plane) == 0) {
					continue;
				}
				BindingCountMap bindings = new BindingCountMap(
						MAXIMUM_JOIN_KEYS, crossComponentPairMask, probed);
				LaneEstimate sampledRows = scanLane(plane, lane, sampled,
						(priority, subject, predicate, object, context) -> bindings.add(
								subject, predicate, object, context),
						scratch);
				if (!sampledRows.available || bindings.overflowed()) {
					laneAvailable = false;
					break;
				}
				if (bindings.size() == 0 && !sampledRows.exact) {
					laneAvailable = false;
					break;
				}
				double inclusion = sampledRows.rowInclusionProbability();
				if (!(inclusion > 0.0d)) {
					laneAvailable = false;
					break;
				}
				laneExact &= sampledRows.exact;
				laneWitnesses = Math.min(laneWitnesses, sampledRows.witnesses);
				for (int entry = 0; entry < bindings.size(); entry++) {
					FrontierLeafProbe boundProbe = bindings.bind(probed, entry);
					SingleLaneEstimate degree = estimateSingleLaneDetailed(boundProbe, crossLane, scratch);
					if (!usableConditionalDegree(degree)) {
						laneAvailable = false;
						break;
					}
					lanePoint = saturatedAdd(lanePoint,
							saturatedMultiply(bindings.count(entry) / inclusion, degree.point()));
					laneExact &= degree.exact();
					laneWitnesses = Math.min(laneWitnesses, degree.witnesses());
				}
				if (!laneAvailable) {
					break;
				}
			}
			if (laneAvailable) {
				if (laneExact) {
					return exactBridgeEstimate(lanePoint);
				}
				lanePoints[available++] = lanePoint;
				sharedWitnesses = Math.min(sharedWitnesses,
						laneWitnesses == Long.MAX_VALUE ? 0L : laneWitnesses);
			}
		}
		if (available == 0) {
			return FrontierJoinEstimate.unavailable(FrontierFallbackReason.CONFIDENCE_TOO_WIDE);
		}
		double productBound = saturatedMultiply(
				estimateLeaf(sampled, scratch).upperRows(), estimateLeaf(probed, scratch).upperRows());
		return sampledJoinEstimate(lanePoints, available, sharedWitnesses, productBound, 2,
				"frontier-v2-omni-bridge");
	}

	private static int transposeCrossComponentPairs(int mask) {
		int transposed = 0;
		for (int left = 0; left < 4; left++) {
			for (int right = 0; right < 4; right++) {
				if ((mask & FrontierJoinProbe.componentPairMask(left, right)) != 0) {
					transposed |= FrontierJoinProbe.componentPairMask(right, left);
				}
			}
		}
		return transposed;
	}

	private FrontierJoinEstimate estimateBridge(FrontierLeafProbe sampled, int sampledComponent,
			FrontierLeafProbe probed, int probedComponent, Scratch scratch) throws IOException {
		if (sampled.boundMask() == 0 || probed.boundMask() == 0) {
			return FrontierJoinEstimate.unavailable(FrontierFallbackReason.UNSUPPORTED_QUERY_SHAPE);
		}
		if ((sampled.boundMask() & 1 << sampledComponent) != 0) {
			long key = sampled.component(sampledComponent);
			if ((probed.boundMask() & 1 << probedComponent) != 0
					&& probed.component(probedComponent) != key) {
				return zeroJoinEstimate();
			}
			if (!validComponentValue(probedComponent, key)) {
				return zeroJoinEstimate();
			}
			FrontierLeafEstimate leftRows = estimateLeaf(sampled, scratch);
			FrontierLeafEstimate rightRows = estimateLeaf(bind(probed, probedComponent, key), scratch);
			return productEstimate(leftRows, rightRows);
		}
		if ((probed.boundMask() & 1 << probedComponent) != 0) {
			long key = probed.component(probedComponent);
			if (!validComponentValue(sampledComponent, key)) {
				return zeroJoinEstimate();
			}
			FrontierLeafEstimate leftRows = estimateLeaf(bind(sampled, sampledComponent, key), scratch);
			FrontierLeafEstimate rightRows = estimateLeaf(probed, scratch);
			return productEstimate(leftRows, rightRows);
		}

		double[] lanePoints = scratch.joinLanePoints(layout.designLanes());
		long sharedWitnesses = Long.MAX_VALUE;
		int available = 0;
		for (int lane = 0; lane < layout.designLanes(); lane++) {
			int crossLane = layout.designLanes() == 1 ? lane : (lane + 1) % layout.designLanes();
			double lanePoint = 0.0d;
			long laneWitnesses = Long.MAX_VALUE;
			boolean laneAvailable = true;
			boolean laneExact = true;
			for (int plane = 0; plane < FrontierOmniLayout.PLANE_COUNT; plane++) {
				if ((sampled.planeMask() & 1 << plane) == 0) {
					continue;
				}
				LongCountMap keys = scratch.counts();
				LaneEstimate sampledRows = scanLane(plane, lane, sampled,
						(priority, subject, predicate, object, context) -> keys.add(
								componentValue(sampledComponent, subject, predicate, object, context)),
						scratch);
				if (!sampledRows.available || keys.overflowed()) {
					laneAvailable = false;
					break;
				}
				if (keys.size() == 0 && !sampledRows.exact) {
					laneAvailable = false;
					break;
				}
				double inclusion = sampledRows.rowInclusionProbability();
				if (!(inclusion > 0.0d)) {
					laneAvailable = false;
					break;
				}
				laneExact &= sampledRows.exact;
				laneWitnesses = Math.min(laneWitnesses, sampledRows.witnesses);
				for (int slot = 0; slot < keys.keys().length; slot++) {
					long key = keys.keys()[slot];
					if (key == 0L) {
						continue;
					}
					SingleLaneEstimate degree = validComponentValue(probedComponent, key)
							? estimateSingleLaneDetailed(bind(probed, probedComponent, key), crossLane, scratch)
							: SingleLaneEstimate.EXACT_ZERO;
					if (!usableConditionalDegree(degree)) {
						laneAvailable = false;
						break;
					}
					lanePoint = saturatedAdd(lanePoint,
							saturatedMultiply(keys.counts()[slot] / inclusion, degree.point()));
					laneExact &= degree.exact();
					laneWitnesses = Math.min(laneWitnesses, degree.witnesses());
				}
				if (!laneAvailable) {
					break;
				}
				if (keys.zeroCount() != 0L) {
					SingleLaneEstimate degree = validComponentValue(probedComponent, 0L)
							? estimateSingleLaneDetailed(bind(probed, probedComponent, 0L), crossLane, scratch)
							: SingleLaneEstimate.EXACT_ZERO;
					if (!usableConditionalDegree(degree)) {
						laneAvailable = false;
						break;
					}
					lanePoint = saturatedAdd(lanePoint,
							saturatedMultiply(keys.zeroCount() / inclusion, degree.point()));
					laneExact &= degree.exact();
					laneWitnesses = Math.min(laneWitnesses, degree.witnesses());
				}
			}
			if (laneAvailable) {
				if (laneExact) {
					return exactBridgeEstimate(lanePoint);
				}
				lanePoints[available++] = lanePoint;
				sharedWitnesses = Math.min(sharedWitnesses,
						laneWitnesses == Long.MAX_VALUE ? 0L : laneWitnesses);
			}
		}
		if (available == 0) {
			return FrontierJoinEstimate.unavailable(FrontierFallbackReason.CONFIDENCE_TOO_WIDE);
		}
		FrontierLeafEstimate sampledRows = estimateLeaf(sampled, scratch);
		FrontierLeafEstimate probedRows = estimateLeaf(probed, scratch);
		double productBound = saturatedMultiply(sampledRows.upperRows(), probedRows.upperRows());
		return sampledJoinEstimate(lanePoints, available, sharedWitnesses, productBound, 2,
				"frontier-v2-omni-bridge");
	}

	private static FrontierJoinEstimate zeroJoinEstimate() {
		return exactBridgeEstimate(0.0d);
	}

	private static FrontierJoinEstimate exactBridgeEstimate(double point) {
		return new FrontierJoinEstimate(point, point, point, 1.0d,
				"frontier-v2-omni-bridge", FrontierFallbackReason.NONE);
	}

	private static boolean validComponentValue(int component, long value) {
		return component == 3 ? value >= 0L : value > 0L;
	}

	private static FrontierJoinEstimate productEstimate(FrontierLeafEstimate left, FrontierLeafEstimate right) {
		double point = saturatedMultiply(left.pointRows(), right.pointRows());
		double lower = saturatedMultiply(left.lowerRows(), right.lowerRows());
		double upper = saturatedMultiply(left.upperRows(), right.upperRows());
		return new FrontierJoinEstimate(point, Math.min(point, lower), Math.max(point, upper),
				Math.min(left.confidence(), right.confidence()), "frontier-v2-omni-bridge",
				FrontierFallbackReason.NONE);
	}

	private double estimateProjectedDistinctLane(FrontierLeafProbe probe, int component, int lane, Scratch scratch)
			throws IOException {
		LongHashSet observed = new LongHashSet(MAXIMUM_DISTINCT_KEYS);
		SamplingAccumulator reference = scratch.distinctSampling();
		boolean scanned = false;
		for (int plane = 0; plane < FrontierOmniLayout.PLANE_COUNT; plane++) {
			if ((probe.planeMask() & 1 << plane) == 0) {
				continue;
			}
			LaneEstimate estimate = scanLane(plane, lane, probe,
					(priority, subject, predicate, object, context) -> observed.add(
							componentValue(component, subject, predicate, object, context)),
					scratch);
			if (!estimate.available) {
				return Double.NaN;
			}
			reference.restrict(estimate);
			scanned = true;
		}
		if (!scanned || observed.overflowed()) {
			return Double.NaN;
		}
		if (observed.size() == 0) {
			// A sampled lane with no witnesses is a valid zero-valued estimator. Dropping it would condition
			// the lane ensemble on positive support and systematically overestimate sparse projections.
			return 0.0d;
		}
		if (reference.isComplete()) {
			return observed.size();
		}

		int crossLane = layout.designLanes() == 1 ? lane : (lane + 1) % layout.designLanes();
		double estimate = 0.0d;
		for (long value : observed.table()) {
			if (value != 0L) {
				estimate = saturatedAdd(estimate,
						distinctWeight(probe, component, value, crossLane, reference, scratch));
			}
		}
		if (observed.containsZero()) {
			estimate = saturatedAdd(estimate,
					distinctWeight(probe, component, 0L, crossLane, reference, scratch));
		}
		return Math.max(observed.size(), estimate);
	}

	private double distinctWeight(FrontierLeafProbe probe, int component, long value, int crossLane,
			SamplingAccumulator reference, Scratch scratch) throws IOException {
		double frequency = estimateSingleLane(bind(probe, component, value), crossLane, scratch);
		double probability = reference.valueInclusionProbability(Math.max(1.0d, frequency));
		return 1.0d / Math.max(Double.MIN_NORMAL, probability);
	}

	private PlaneEstimate estimatePlane(int plane, FrontierLeafProbe probe, Scratch scratch) throws IOException {
		double[] points = scratch.lanePoints(layout.designLanes());
		int priorityTier = INITIAL_LEAF_PRIORITY_TIER;
		while (true) {
			double lower = Double.MAX_VALUE;
			double upper = 0.0d;
			long sharedWitnesses = Long.MAX_VALUE;
			boolean exact = true;
			boolean exhausted = true;
			int available = 0;
			for (int lane = 0; lane < layout.designLanes(); lane++) {
				LaneEstimate estimate = scanLane(plane, lane, probe, null, scratch, priorityTier);
				if (!estimate.available) {
					continue;
				}
				if (estimate.exact && estimate.point == 0.0d) {
					return new PlaneEstimate(true, 0.0d, 0.0d, 0.0d, 1.0d, true);
				}
				points[available++] = estimate.point;
				lower = Math.min(lower, estimate.lower);
				upper = Math.max(upper, estimate.upper);
				sharedWitnesses = Math.min(sharedWitnesses, estimate.witnesses);
				exact &= estimate.exact;
				exhausted &= estimate.exhausted;
			}
			if (available == 0) {
				return PlaneEstimate.UNAVAILABLE;
			}
			Arrays.sort(points, 0, available);
			double point = points[available / 2];
			if ((available & 1) == 0) {
				point = points[available / 2 - 1] * 0.5d + point * 0.5d;
			}
			FrontierSamplingQuality quality = FrontierSamplingQuality.fromLanes(
					points, available, sharedWitnesses, 1.0d, 1, false);
			if (exact || exhausted || !quality.isWeak(MINIMUM_STRONG_WITNESSES,
					MAXIMUM_STRONG_REPLICA_ERROR, MINIMUM_STRONG_REPRESENTED_MASS)) {
				double confidence = exact ? 1.0d : quality.confidence();
				if (!exact) {
					double qualityError = Double.isFinite(quality.relativeStandardError())
							? saturatedMultiply(point, 2.0d * quality.relativeStandardError())
							: Double.MAX_VALUE;
					lower = Math.min(lower, Math.max(0.0d, point - qualityError));
					upper = Math.max(upper, saturatedAdd(point, qualityError));
				}
				return new PlaneEstimate(true, point, Math.min(point, lower), Math.max(point, upper), confidence,
						exact);
			}
			priorityTier = priorityTier >= Integer.MAX_VALUE / 2 ? Integer.MAX_VALUE : priorityTier * 2;
		}
	}

	private LaneEstimate scanLane(int plane, int lane, FrontierLeafProbe probe, TupleConsumer consumer,
			Scratch scratch)
			throws IOException {
		return scanLane(plane, lane, probe, consumer, scratch, Integer.MAX_VALUE);
	}

	private LaneEstimate scanLane(int plane, int lane, FrontierLeafProbe probe, TupleConsumer consumer,
			Scratch scratch, int maximumCandidateRows)
			throws IOException {
		int selectedCells = Math.multiplyExact(Integer.bitCount(probe.boundMask()), layout.depth());
		CellSlice[] slices = scratch.cellSlices(selectedCells);
		int selected = 0;
		long minimumPopulation = Long.MAX_VALUE;
		SamplingAccumulator reference = scratch.laneSampling();
		boolean complete = true;
		int candidate = -1;
		int candidateRows = Integer.MAX_VALUE;
		int completeCandidate = -1;
		int completeCandidateRows = Integer.MAX_VALUE;
		for (int component = 0; component < FrontierOmniLayout.COMPONENT_COUNT; component++) {
			if ((probe.boundMask() & 1 << component) == 0) {
				continue;
			}
			for (int row = 0; row < layout.depth(); row++) {
				int cell = layout.cell(plane, lane, component, row, probe.component(component));
				CellSlice slice = slice(cell, slices[selected]);
				if (slice.population == 0L) {
					return LaneEstimate.exactZero();
				}
				if (!slice.authoritative()) {
					return LaneEstimate.UNAVAILABLE;
				}
				slices[selected] = slice;
				minimumPopulation = Math.min(minimumPopulation, slice.population);
				slice.restrictSampling(reference);
				complete &= slice.complete();
				if (slice.count < candidateRows) {
					candidate = selected;
					candidateRows = slice.count;
				}
				if (slice.complete() && slice.count < completeCandidateRows) {
					completeCandidate = selected;
					completeCandidateRows = slice.count;
				}
				selected++;
			}
		}
		if (candidate < 0) {
			return LaneEstimate.UNAVAILABLE;
		}

		if (completeCandidate >= 0) {
			candidate = completeCandidate;
		}
		CellSlice candidateSlice = slices[candidate];
		boolean progressive = deltaIndex.isEmpty() && maximumCandidateRows < candidateSlice.count;
		int scannedCandidateRows = progressive ? maximumCandidateRows : candidateSlice.count;
		if (progressive) {
			candidateSlice.restrictPrefixSampling(reference, scannedCandidateRows);
		}
		scratch.recordCandidateRows(scannedCandidateRows);
		long matched = candidateSlice.countMatches(
				probe, slices, selected, candidate, consumer, progressive ? scannedCandidateRows : Integer.MAX_VALUE);
		if (!progressive && (candidateSlice.complete() || complete)) {
			return LaneEstimate.exact(matched);
		}
		double inclusion = reference.rowInclusionProbability();
		double point = Math.min(minimumPopulation, matched / Math.max(Double.MIN_NORMAL, inclusion));
		double error = matched == 0L ? minimumPopulation : Math.max(1.0d, 4.0d * point / Math.sqrt(matched));
		double lower = Math.max(0.0d, point - error);
		double upper = Math.min(minimumPopulation, saturatedAdd(point, error));
		return LaneEstimate.sampled(point, Math.min(point, lower), Math.max(point, upper), matched, reference,
				!progressive);
	}

	private double estimateSingleLane(FrontierLeafProbe probe, int lane, Scratch scratch) throws IOException {
		SingleLaneEstimate estimate = estimateSingleLaneDetailed(probe, lane, scratch);
		return estimate.available() ? estimate.point() : Double.NaN;
	}

	private SingleLaneEstimate estimateSingleLaneDetailed(FrontierLeafProbe probe, int lane, Scratch scratch)
			throws IOException {
		double point = 0.0d;
		long witnesses = Long.MAX_VALUE;
		boolean exact = true;
		for (int plane = 0; plane < FrontierOmniLayout.PLANE_COUNT; plane++) {
			if ((probe.planeMask() & 1 << plane) == 0) {
				continue;
			}
			LaneEstimate estimate = scanLane(plane, lane, probe, null, scratch);
			if (!estimate.available) {
				return SingleLaneEstimate.UNAVAILABLE;
			}
			point = saturatedAdd(point, estimate.point);
			witnesses = Math.min(witnesses, estimate.witnesses);
			exact &= estimate.exact;
		}
		return new SingleLaneEstimate(true, point, exact, witnesses == Long.MAX_VALUE ? 0L : witnesses);
	}

	private static boolean usableConditionalDegree(SingleLaneEstimate estimate) {
		return estimate.available() && (estimate.exact() || estimate.point() > 0.0d);
	}

	private CellSlice slice(int cell, CellSlice target) throws IOException {
		long population = directory.column(0).value(cell);
		int domainId = Math.toIntExact(directory.column(1).value(cell));
		int start = Math.toIntExact(directory.column(2).value(cell));
		int count = Math.toIntExact(directory.column(3).value(cell));
		int flags = Math.toIntExact(directory.column(4).value(cell));
		int numerator = Math.toIntExact(directory.column(5).value(cell));
		long cutoffPriority = directory.column(6).value(cell);
		if ((flags & ~FrontierOmniCellFlags.KNOWN_MASK) != 0 || start < 0 || count < 0 || numerator < 0) {
			throw new IOException("Frontier Omni cell directory contains invalid metadata");
		}
		Domain domain = domains.get(domainId);
		if (count != 0 && (domain == null || start > domain.rows() - count)) {
			throw new IOException("Frontier Omni cell posting slice is outside its tuple domain");
		}
		target.reset(population, domain, start, count, flags, numerator, cutoffPriority,
				deltaIndex, cell, layout.lane(cell), layout.plane(cell));
		return target;
	}

	private double globalProjectedDistinct(FrontierStatisticsShardDescriptor descriptor, int planeMask,
			int component) throws IOException {
		FrontierStatisticsShard shard = shards.get(descriptor.shardId());
		int precision = Math.toIntExact(descriptor.logicalKey());
		int registerCount = 1 << precision;
		double inverseSum = 0.0d;
		int zeros = 0;
		for (int register = 0; register < registerCount; register++) {
			long rank = 0L;
			for (int plane = 0; plane < FrontierOmniLayout.PLANE_COUNT; plane++) {
				if ((planeMask & 1 << plane) != 0) {
					long offset = ((long) plane * FrontierOmniLayout.COMPONENT_COUNT + component)
							* registerCount + register;
					rank = Math.max(rank, shard.column(0).value(offset));
				}
			}
			inverseSum += Math.scalb(1.0d, -Math.toIntExact(rank));
			zeros += rank == 0L ? 1 : 0;
		}
		return hllEstimate(registerCount, inverseSum, zeros);
	}

	private static FrontierLeafProbe bind(FrontierLeafProbe probe, int component, long value) {
		return new FrontierLeafProbe(probe.planeMask(), probe.boundMask() | 1 << component,
				component == 0 ? value : probe.subjectId(),
				component == 1 ? value : probe.predicateId(),
				component == 2 ? value : probe.objectId(),
				component == 3 ? value : probe.contextId(), probe.repeatedComponentPairMask(),
				probe.namedContextsOnly());
	}

	private static FrontierLeafProbe bind(FrontierLeafProbe probe, int componentMask,
			long subject, long predicate, long object, long context) {
		return new FrontierLeafProbe(probe.planeMask(), probe.boundMask() | componentMask,
				(componentMask & FrontierLeafProbe.SUBJECT) == 0 ? probe.subjectId() : subject,
				(componentMask & FrontierLeafProbe.PREDICATE) == 0 ? probe.predicateId() : predicate,
				(componentMask & FrontierLeafProbe.OBJECT) == 0 ? probe.objectId() : object,
				(componentMask & FrontierLeafProbe.CONTEXT) == 0 ? probe.contextId() : context,
				probe.repeatedComponentPairMask(), probe.namedContextsOnly());
	}

	private static long componentValue(int component, long subject, long predicate, long object, long context) {
		return switch (component) {
		case 0 -> subject;
		case 1 -> predicate;
		case 2 -> object;
		case 3 -> context;
		default -> throw new IllegalArgumentException("Frontier component must be in [0, 3]");
		};
	}

	private static double inclusionProbability(double rowProbability, double frequency) {
		if (rowProbability >= 1.0d) {
			return 1.0d;
		}
		return -Math.expm1(frequency * Math.log1p(-rowProbability));
	}

	static double bottomKInclusionProbability(long population, int sampleSize, double frequency) {
		if (population <= 0L || sampleSize <= 0 || !(frequency > 0.0d)) {
			return 0.0d;
		}
		long samples = Math.min(population, sampleSize);
		if (samples == population) {
			return 1.0d;
		}
		double boundedFrequency = Math.min((double) population, frequency);
		long successes = boundedFrequency >= population
				? population
				: Math.max(1L, Math.round(boundedFrequency));
		if (successes > population - samples) {
			return 1.0d;
		}
		if (successes == 1L) {
			return (double) samples / population;
		}

		double logNone;
		if (Math.min(successes, samples) <= 64L) {
			logNone = 0.0d;
			if (successes <= samples) {
				for (long index = 0L; index < successes; index++) {
					logNone += Math.log1p(-(double) samples / (population - index));
				}
			} else {
				for (long index = 0L; index < samples; index++) {
					logNone += Math.log1p(-(double) successes / (population - index));
				}
			}
		} else {
			long failures = population - successes;
			logNone = logFallingFactorial(failures, samples) - logFallingFactorial(population, samples);
		}
		return Math.max(0.0d, Math.min(1.0d, -Math.expm1(Math.min(0.0d, logNone))));
	}

	private static double logFallingFactorial(long population, long sampleSize) {
		return logGamma(population + 1.0d) - logGamma(population - sampleSize + 1.0d);
	}

	private static double logGamma(double value) {
		double shifted = value - 1.0d;
		double series = 0.99999999999980993d;
		for (int index = 0; index < LANCZOS_COEFFICIENTS.length; index++) {
			series += LANCZOS_COEFFICIENTS[index] / (shifted + index + 1.0d);
		}
		double scale = shifted + 7.5d;
		return LOG_TWO_PI_OVER_TWO + (shifted + 0.5d) * Math.log(scale) - scale + Math.log(series);
	}

	private static boolean matchesProbe(Domain domain, long ordinal, FrontierLeafProbe probe) throws IOException {
		long subject = domain.term(ordinal, 2);
		long predicate = domain.term(ordinal, 3);
		long object = domain.term(ordinal, 4);
		long context = domain.term(ordinal, 5);
		return matchesProbe(subject, predicate, object, context, probe);
	}

	private static boolean matchesProbe(long subject, long predicate, long object, long context,
			FrontierLeafProbe probe) {
		return (!probe.namedContextsOnly() || context != 0L)
				&& ((probe.boundMask() & FrontierLeafProbe.SUBJECT) == 0
						|| subject == probe.subjectId())
				&& ((probe.boundMask() & FrontierLeafProbe.PREDICATE) == 0
						|| predicate == probe.predicateId())
				&& ((probe.boundMask() & FrontierLeafProbe.OBJECT) == 0
						|| object == probe.objectId())
				&& ((probe.boundMask() & FrontierLeafProbe.CONTEXT) == 0
						|| context == probe.contextId())
				&& matchesRepeatedComponents(probe.repeatedComponentPairMask(), subject, predicate, object, context);
	}

	private static boolean matchesRepeatedComponents(int mask, long subject, long predicate, long object,
			long context) {
		return ((mask & FrontierLeafProbe.SUBJECT_PREDICATE_EQUAL) == 0 || subject == predicate)
				&& ((mask & FrontierLeafProbe.SUBJECT_OBJECT_EQUAL) == 0 || subject == object)
				&& ((mask & FrontierLeafProbe.SUBJECT_CONTEXT_EQUAL) == 0 || subject == context)
				&& ((mask & FrontierLeafProbe.PREDICATE_OBJECT_EQUAL) == 0 || predicate == object)
				&& ((mask & FrontierLeafProbe.PREDICATE_CONTEXT_EQUAL) == 0 || predicate == context)
				&& ((mask & FrontierLeafProbe.OBJECT_CONTEXT_EQUAL) == 0 || object == context);
	}

	private static void putDomainDescriptor(Map<Integer, FrontierStatisticsShardDescriptor> target,
			FrontierStatisticsShardDescriptor descriptor) throws IOException {
		int domain = Math.toIntExact(descriptor.logicalKey());
		if (target.putIfAbsent(domain, descriptor) != null) {
			throw new IOException("Frontier generation contains a duplicate Omni tuple/posting domain");
		}
	}

	private static double hllEstimate(int registerCount, double inverseSum, int zeros) {
		double alpha = switch (registerCount) {
		case 16 -> 0.673d;
		case 32 -> 0.697d;
		case 64 -> 0.709d;
		default -> 0.7213d / (1.0d + 1.079d / registerCount);
		};
		double estimate = alpha * registerCount * registerCount / inverseSum;
		return estimate <= 2.5d * registerCount && zeros > 0
				? registerCount * Math.log((double) registerCount / zeros)
				: estimate;
	}

	private static double saturatedAdd(double left, double right) {
		double sum = left + right;
		return Double.isFinite(sum) ? sum : Double.MAX_VALUE;
	}

	private static double saturatedMultiply(double left, double right) {
		double product = left * right;
		return Double.isFinite(product) ? Math.max(0.0d, product) : Double.MAX_VALUE;
	}

	private static double saturatedAverage(double left, double right) {
		return left * 0.5d + right * 0.5d;
	}

	private static FrontierJoinEstimate sampledJoinEstimate(double[] lanePoints, int available,
			long sharedWitnesses, double productBound, int compositionDepth, String source) {
		if (lanePoints == null || available <= 0 || available > lanePoints.length || sharedWitnesses < 0L
				|| Double.isNaN(productBound) || productBound < 0.0d || compositionDepth < 1) {
			throw new IllegalArgumentException("Frontier sampled join ensemble is invalid");
		}
		Arrays.sort(lanePoints, 0, available);
		double point = Math.min(productBound, lanePoints[available / 2]);
		if ((available & 1) == 0) {
			point = Math.min(productBound, saturatedAverage(lanePoints[available / 2 - 1], point));
		}
		FrontierSamplingQuality quality = FrontierSamplingQuality.fromLanes(
				lanePoints, available, sharedWitnesses, 1.0d, compositionDepth, false);
		if (quality.isWeak(MINIMUM_STRONG_WITNESSES, MAXIMUM_STRONG_REPLICA_ERROR,
				MINIMUM_STRONG_REPRESENTED_MASS)) {
			return new FrontierJoinEstimate(point, 0.0d, productBound, quality.confidence(), source,
					FrontierFallbackReason.NONE);
		}
		double supportError = 4.0d / Math.sqrt(Math.max(1.0d, quality.effectiveSampleSize()));
		double replicaError = 2.0d * quality.relativeStandardError();
		double depthScale = Math.sqrt(1.0d + 0.15d * (compositionDepth - 1));
		double error = saturatedMultiply(point, Math.max(supportError, replicaError) * depthScale);
		double lower = Math.max(0.0d, point - error);
		double upper = Math.min(productBound, saturatedAdd(point, error));
		return new FrontierJoinEstimate(point, Math.min(point, lower), Math.max(point, upper), quality.confidence(),
				source, FrontierFallbackReason.NONE);
	}

	@FunctionalInterface
	private interface TupleConsumer {

		void accept(long priority, long subject, long predicate, long object, long context) throws IOException;
	}

	private static final class Domain {

		private final FrontierStatisticsShard tuples;
		private final FrontierStatisticsShard postings;

		private Domain(FrontierStatisticsShard tuples, FrontierStatisticsShard postings) {
			this.tuples = tuples;
			this.postings = postings;
		}

		private long rows() {
			return postings.rowCount();
		}

		private long postingOrdinal(long posting) throws IOException {
			long ordinal = postings.column(0).value(posting);
			if (ordinal < 0L || ordinal >= tuples.rowCount()) {
				throw new IOException("Frontier Omni posting references an invalid tuple ordinal");
			}
			return ordinal;
		}

		private long priority(long ordinal) throws IOException {
			return tuples.column(0).value(ordinal);
		}

		private long term(long ordinal, int column) throws IOException {
			return tuples.column(column).value(ordinal);
		}
	}

	/** Mutable buffers owned by one query lease; never stored on the shared mapped generation. */
	static final class Scratch {

		private CellSlice[] cellSlices = new CellSlice[0];
		private double[] lanePoints = new double[0];
		private double[] joinLanePoints = new double[0];
		private ParticleBuffer firstParticles;
		private ParticleBuffer secondParticles;
		private TupleBuffer tuples;
		private boolean[] knownClasses = new boolean[0];
		private LongCountMap counts;
		private final SamplingAccumulator laneSampling = new SamplingAccumulator();
		private final SamplingAccumulator distinctSampling = new SamplingAccumulator();
		private long candidateRowsVisited;

		private CellSlice[] cellSlices(int required) {
			if (cellSlices.length < required) {
				int previous = cellSlices.length;
				cellSlices = Arrays.copyOf(cellSlices, required);
				for (int index = previous; index < required; index++) {
					cellSlices[index] = new CellSlice();
				}
			}
			return cellSlices;
		}

		private double[] lanePoints(int required) {
			if (lanePoints.length < required) {
				lanePoints = new double[required];
			}
			return lanePoints;
		}

		private double[] joinLanePoints(int required) {
			if (joinLanePoints.length < required) {
				joinLanePoints = new double[required];
			}
			return joinLanePoints;
		}

		private void recordCandidateRows(int rows) {
			candidateRowsVisited = Long.MAX_VALUE - candidateRowsVisited < rows
					? Long.MAX_VALUE
					: candidateRowsVisited + rows;
		}

		long candidateRowsVisited() {
			return candidateRowsVisited;
		}

		ParticleBuffer firstParticles(int rowWidth) {
			if (firstParticles == null) {
				firstParticles = new ParticleBuffer(MAXIMUM_PATH_PARTICLES, PATH_PARTICLE_BUFFER_BYTES);
			}
			firstParticles.reset(rowWidth);
			return firstParticles;
		}

		ParticleBuffer secondParticles(int rowWidth) {
			if (secondParticles == null) {
				secondParticles = new ParticleBuffer(MAXIMUM_PATH_PARTICLES, PATH_PARTICLE_BUFFER_BYTES);
			}
			secondParticles.reset(rowWidth);
			return secondParticles;
		}

		private TupleBuffer tuples() {
			if (tuples == null) {
				tuples = new TupleBuffer(MAXIMUM_PATH_TUPLES);
			}
			tuples.clear();
			return tuples;
		}

		boolean[] knownClasses(int rowWidth) {
			if (knownClasses.length < rowWidth) {
				knownClasses = new boolean[rowWidth];
			} else {
				Arrays.fill(knownClasses, 0, rowWidth, false);
			}
			return knownClasses;
		}

		private LongCountMap counts() {
			if (counts == null) {
				counts = new LongCountMap(MAXIMUM_JOIN_KEYS);
			} else {
				counts.clear();
			}
			return counts;
		}

		private SamplingAccumulator laneSampling() {
			laneSampling.reset();
			return laneSampling;
		}

		private SamplingAccumulator distinctSampling() {
			distinctSampling.reset();
			return distinctSampling;
		}
	}

	private static final class CellSlice {

		private long basePopulation;
		private long population;
		private Domain domain;
		private int start;
		private int baseCount;
		private int count;
		private int flags;
		private int numerator;
		private long cutoffPriority;
		private FrontierOmniDeltaIndex deltaIndex;
		private int lane;
		private int plane;
		private int authorityFloor;
		private long[] deltaDirectoryRows = new long[0];
		private long[] positions = new long[0];
		private long[] ends = new long[0];
		private int[] sourceHeap = new int[0];

		private void reset(long population, Domain domain, int start, int count, int flags, int numerator,
				long cutoffPriority, FrontierOmniDeltaIndex deltaIndex, int cell, int lane, int plane)
				throws IOException {
			basePopulation = population;
			this.population = population;
			this.domain = domain;
			this.start = start;
			baseCount = count;
			this.count = count;
			this.flags = flags;
			this.numerator = numerator;
			this.cutoffPriority = cutoffPriority;
			this.deltaIndex = deltaIndex;
			this.lane = lane;
			this.plane = plane;
			authorityFloor = 0;
			int layers = deltaIndex.layerCount();
			if (deltaDirectoryRows.length < layers) {
				deltaDirectoryRows = new long[layers];
			}
			Arrays.fill(deltaDirectoryRows, 0, layers, -1L);
			long sampleRows = count;
			try {
				for (int layer = 0; layer < layers; layer++) {
					long row = deltaIndex.findCell(layer, cell);
					deltaDirectoryRows[layer] = row;
					if (row < 0L) {
						continue;
					}
					this.population = Math.addExact(this.population, deltaIndex.populationDelta(layer, row));
					sampleRows = Math.addExact(sampleRows, deltaIndex.sampleDelta(layer, row));
					int floor = deltaIndex.authorityFloor(layer, row);
					if (authorityFloor != 0 && floor != 0 && authorityFloor != floor) {
						throw new IOException("Frontier Omni delta layers disagree on a cell authority floor");
					}
					authorityFloor = Math.max(authorityFloor, floor);
				}
				this.count = Math.toIntExact(sampleRows);
			} catch (ArithmeticException overflow) {
				throw new IOException("Frontier Omni delta cell cardinality overflow", overflow);
			}
			if (this.population < 0L || this.count < 0 || this.count > this.population) {
				throw new IOException("Frontier Omni delta produces an invalid cell population");
			}
			if (complete() && this.count != this.population) {
				throw new IOException("Frontier Omni complete cell lost exact mutation coverage");
			}
		}

		private boolean authoritative() {
			return (flags & FrontierOmniCellFlags.AUTHORITATIVE) != 0
					&& (complete() || count >= authorityFloor);
		}

		private boolean complete() {
			return (flags & FrontierOmniCellFlags.COMPLETE) != 0;
		}

		private void restrictSampling(SamplingAccumulator reference) {
			if (complete()) {
				return;
			}
			if (!deltaIndex.isEmpty()) {
				if ((flags & FrontierOmniCellFlags.BOTTOM_K) != 0) {
					double probability = SamplingAccumulator.bottomKCutoffFraction(cutoffPriority);
					reference.restrictFixedThreshold(population, probability);
					return;
				}
				double probability = basePopulation == 0L ? 0.0d : (double) numerator / basePopulation;
				reference.restrictFixedThreshold(population, probability);
				return;
			}
			if ((flags & FrontierOmniCellFlags.BOTTOM_K) != 0) {
				reference.restrictBottomK(population, numerator, cutoffPriority);
				return;
			}
			reference.restrictThreshold(population, numerator);
		}

		private void restrictPrefixSampling(SamplingAccumulator reference, int prefixRows) throws IOException {
			if (prefixRows <= 0 || prefixRows >= count || !deltaIndex.isEmpty()) {
				throw new IllegalArgumentException("Frontier Omni priority prefix is invalid");
			}
			long ordinal = domain.postingOrdinal((long) start + prefixRows - 1L);
			reference.restrictBottomK(population, prefixRows, domain.priority(ordinal));
		}

		private long countMatches(FrontierLeafProbe probe, CellSlice[] slices, int selected, int candidate,
				TupleConsumer consumer, int maximumBaseRows) throws IOException {
			int sources = deltaIndex.layerCount() + 1;
			if (positions.length < sources) {
				positions = new long[sources];
				ends = new long[sources];
				sourceHeap = new int[sources];
			}
			positions[0] = start;
			ends[0] = (long) start + Math.min(baseCount, maximumBaseRows);
			for (int source = 1; source < sources; source++) {
				long directoryRow = deltaDirectoryRows[source - 1];
				if (directoryRow < 0L) {
					positions[source] = 0L;
					ends[source] = 0L;
				} else {
					positions[source] = deltaIndex.postingStart(source - 1, directoryRow);
					ends[source] = deltaIndex.postingEnd(source - 1, directoryRow);
				}
			}

			int heapSize = 0;
			for (int source = 0; source < sources; source++) {
				if (positions[source] < ends[source]) {
					heapSize = heapAdd(heapSize, source);
				}
			}
			long matched = 0L;
			while (heapSize != 0) {
				int firstSource = sourceHeap[0];
				long priority = sourcePriority(firstSource);
				int tuplePlane = sourcePlane(firstSource);
				long subject = sourceTerm(firstSource, 0);
				long predicate = sourceTerm(firstSource, 1);
				long object = sourceTerm(firstSource, 2);
				long context = sourceTerm(firstSource, 3);
				if (tuplePlane != plane) {
					throw new IOException("Frontier Omni posting and tuple statement planes disagree");
				}

				boolean basePresent = false;
				long transition = 0L;
				while (heapSize != 0 && compareSourceTo(sourceHeap[0], priority, tuplePlane,
						subject, predicate, object, context) == 0) {
					int source = sourceHeap[0];
					heapSize = heapRemoveFirst(heapSize);
					while (positions[source] < ends[source]
							&& compareSourceTo(source, priority, tuplePlane, subject, predicate, object,
									context) == 0) {
						if (source == 0) {
							if (basePresent) {
								throw new IOException("Frontier Omni base sample contains a duplicate tuple");
							}
							basePresent = true;
						} else {
							transition = Math.addExact(transition,
									deltaIndex.direction(source - 1, sourceOrdinal(source)));
						}
						positions[source]++;
					}
					if (positions[source] < ends[source]) {
						heapSize = heapAdd(heapSize, source);
					}
				}
				long present = (basePresent ? 1L : 0L) + transition;
				if (present != 0L && present != 1L) {
					throw new IOException("Frontier Omni mutation history is not an effective set transition");
				}
				if (present == 0L || !matchesProbe(subject, predicate, object, context, probe)) {
					continue;
				}
				boolean inIntersection = complete();
				if (!inIntersection) {
					inIntersection = true;
					for (int other = 0; other < selected; other++) {
						if (other == candidate) {
							continue;
						}
						boolean contains = basePresent
								? slices[other].contains(priority, tuplePlane, subject, predicate, object, context)
								: slices[other].acceptsOverlay(priority);
						if (!contains) {
							inIntersection = false;
							break;
						}
					}
				}
				if (inIntersection) {
					matched++;
					if (consumer != null) {
						consumer.accept(priority, subject, predicate, object, context);
					}
				}
			}
			if (matched > count) {
				throw new IOException("Frontier Omni merged candidate count exceeds its cell directory");
			}
			return matched;
		}

		private int heapAdd(int size, int source) throws IOException {
			int child = size;
			while (child > 0) {
				int parent = (child - 1) >>> 1;
				if (compareSources(sourceHeap[parent], source) <= 0) {
					break;
				}
				sourceHeap[child] = sourceHeap[parent];
				child = parent;
			}
			sourceHeap[child] = source;
			return size + 1;
		}

		private int heapRemoveFirst(int size) throws IOException {
			int reduced = size - 1;
			if (reduced == 0) {
				return 0;
			}
			int replacement = sourceHeap[reduced];
			int parent = 0;
			while (true) {
				int left = parent * 2 + 1;
				if (left >= reduced) {
					break;
				}
				int right = left + 1;
				int child = right < reduced && compareSources(sourceHeap[right], sourceHeap[left]) < 0
						? right
						: left;
				if (compareSources(replacement, sourceHeap[child]) <= 0) {
					break;
				}
				sourceHeap[parent] = sourceHeap[child];
				parent = child;
			}
			sourceHeap[parent] = replacement;
			return reduced;
		}

		private boolean acceptsOverlay(long priority) {
			if (!authoritative()) {
				return false;
			}
			if (complete()) {
				return true;
			}
			if ((flags & FrontierOmniCellFlags.BOTTOM_K) != 0) {
				return Long.compareUnsigned(priority, cutoffPriority) <= 0;
			}
			return (flags & FrontierOmniCellFlags.THRESHOLD_SAMPLE) != 0 && basePopulation > 0L
					&& FrontierStatisticsHash.unsignedMultiplyHigh(priority, basePopulation) < numerator;
		}

		private int compareSources(int left, int right) throws IOException {
			long leftPriority = sourcePriority(left);
			long rightPriority = sourcePriority(right);
			int compared = Long.compareUnsigned(leftPriority, rightPriority);
			if (compared == 0) {
				compared = Integer.compare(sourcePlane(left), sourcePlane(right));
			}
			for (int component = 0; compared == 0 && component < FrontierOmniLayout.COMPONENT_COUNT; component++) {
				compared = Long.compare(sourceTerm(left, component), sourceTerm(right, component));
			}
			return compared;
		}

		private int compareSourceTo(int source, long priority, int tuplePlane, long subject, long predicate,
				long object, long context) throws IOException {
			int compared = Long.compareUnsigned(sourcePriority(source), priority);
			if (compared == 0) {
				compared = Integer.compare(sourcePlane(source), tuplePlane);
			}
			for (int component = 0; compared == 0 && component < FrontierOmniLayout.COMPONENT_COUNT; component++) {
				long expected = componentValue(component, subject, predicate, object, context);
				compared = Long.compare(sourceTerm(source, component), expected);
			}
			return compared;
		}

		private long sourceOrdinal(int source) throws IOException {
			if (source == 0) {
				return domain.postingOrdinal(positions[0]);
			}
			return deltaIndex.postingOrdinal(source - 1, positions[source]);
		}

		private long sourcePriority(int source) throws IOException {
			long ordinal = sourceOrdinal(source);
			return source == 0 ? domain.priority(ordinal) : deltaIndex.priority(source - 1, ordinal, lane);
		}

		private int sourcePlane(int source) throws IOException {
			long ordinal = sourceOrdinal(source);
			return source == 0 ? Math.toIntExact(domain.term(ordinal, 1)) : deltaIndex.plane(source - 1, ordinal);
		}

		private long sourceTerm(int source, int component) throws IOException {
			long ordinal = sourceOrdinal(source);
			return source == 0 ? domain.term(ordinal, component + 2)
					: deltaIndex.term(source - 1, ordinal, component);
		}

		private boolean contains(long priority, int tuplePlane, long subject, long predicate, long object, long context)
				throws IOException {
			long low = start;
			long high = (long) start + baseCount - 1L;
			while (low <= high) {
				long middle = low + (high - low >>> 1);
				long ordinal = domain.postingOrdinal(middle);
				int compared = Long.compareUnsigned(domain.priority(ordinal), priority);
				if (compared < 0) {
					low = middle + 1L;
				} else if (compared > 0) {
					high = middle - 1L;
				} else {
					long first = middle;
					while (first > start) {
						long previousOrdinal = domain.postingOrdinal(first - 1L);
						if (domain.priority(previousOrdinal) != priority) {
							break;
						}
						first--;
					}
					long end = (long) start + baseCount;
					for (long match = first; match < end; match++) {
						long matchOrdinal = domain.postingOrdinal(match);
						if (domain.priority(matchOrdinal) != priority) {
							break;
						}
						if (domain.term(matchOrdinal, 1) == tuplePlane
								&& domain.term(matchOrdinal, 2) == subject
								&& domain.term(matchOrdinal, 3) == predicate
								&& domain.term(matchOrdinal, 4) == object
								&& domain.term(matchOrdinal, 5) == context) {
							return true;
						}
					}
					return false;
				}
			}
			return false;
		}
	}

	private record LaneEstimate(boolean available, double point, double lower, double upper, long witnesses,
			boolean exact, SamplingMode samplingMode, long samplingPopulation, int samplingSize,
			double samplingRowInclusionProbability, long samplingCutoffPriority, boolean exhausted) {

		private static final LaneEstimate UNAVAILABLE = new LaneEstimate(false, 0.0d, 0.0d, Double.MAX_VALUE, 0L,
				false, SamplingMode.UNAVAILABLE, 0L, 0, 0.0d, 0L, true);

		private static LaneEstimate exactZero() {
			return exact(0L);
		}

		private static LaneEstimate exact(long rows) {
			return new LaneEstimate(true, rows, rows, rows, rows, true, SamplingMode.COMPLETE, 0L, 0, 1.0d,
					-1L, true);
		}

		private static LaneEstimate sampled(double point, double lower, double upper, long witnesses,
				SamplingAccumulator reference, boolean exhausted) {
			return new LaneEstimate(true, point, lower, upper, witnesses, false, reference.mode,
					reference.population, reference.sampleSize, reference.rowInclusionProbability,
					reference.cutoffPriority, exhausted);
		}

		private double rowInclusionProbability() {
			return samplingRowInclusionProbability;
		}
	}

